import time

class CircuitBreaker:
    def __init__(self, threshold=3, cooldown=0.2):
        self.threshold, self.cooldown = threshold, cooldown
        self.state, self.fails, self.opened_at = "CLOSED", 0, 0.0

    def call(self, fn):
        if self.state == "OPEN":
            if time.time() - self.opened_at < self.cooldown:
                return "rejected (fallback)"      # fail fast, no call made
            self.state = "HALF_OPEN"              # cool-down over: allow one probe
        try:
            r = fn()
        except Exception:
            self.fails += 1
            if self.state == "HALF_OPEN" or self.fails >= self.threshold:
                self.state, self.opened_at = "OPEN", time.time()
            return "error"
        self.state, self.fails = "CLOSED", 0      # success closes the circuit
        return r

healthy = {"up": False}
def dependency():
    if not healthy["up"]:
        raise RuntimeError("down")
    return "ok"

cb = CircuitBreaker()
for i in range(6):
    print(i, cb.call(dependency), cb.state)
time.sleep(0.25)
healthy["up"] = True
print("after cooldown", cb.call(dependency), cb.state)
# Each call is O(1) time and space.
